    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: warranty; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.warranty (
    id text NOT NULL,
    closeout_id text NOT NULL,
    item_description text NOT NULL,
    supplier text,
    start_date date,
    expiry_date date,
    created_at timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by text NOT NULL,
    updated_at timestamp(3) without time zone NOT NULL,
    updated_by text NOT NULL,
    deleted_at timestamp(3) without time zone,
    deleted_by text
);


--
-- Name: work_from_home_day; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.work_from_home_day (
    id text NOT NULL,
    company_id text NOT NULL,
    date date NOT NULL,
    reason text NOT NULL,
    scope public."WorkFromHomeScope" DEFAULT 'ALL'::public."WorkFromHomeScope" NOT NULL,
    department_ids text[] DEFAULT ARRAY[]::text[],
    employee_ids text[] DEFAULT ARRAY[]::text[],
    created_at timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by text NOT NULL,
    updated_at timestamp(3) without time zone NOT NULL,
    updated_by text NOT NULL,
    deleted_at timestamp(3) without time zone,
    deleted_by text,
    created_from_attendance_import boolean DEFAULT false NOT NULL
);


--
-- Name: work_schedule; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.work_schedule (
    id text NOT NULL,
    company_id text NOT NULL,
    name text NOT NULL,
    description text,
    is_default boolean DEFAULT false NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by text NOT NULL,
    updated_at timestamp(3) without time zone NOT NULL,
    updated_by text NOT NULL,
    deleted_at timestamp(3) without time zone,
    deleted_by text,
    check_mode public."WorkScheduleCheckMode" DEFAULT 'STANDARD'::public."WorkScheduleCheckMode" NOT NULL,
    latest_scan_time text
);


--
-- Name: work_schedule_day; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.work_schedule_day (
    id text NOT NULL,
    schedule_id text NOT NULL,
    day_of_week integer NOT NULL,
    is_working_day boolean DEFAULT true NOT NULL,
    is_half_day boolean DEFAULT false NOT NULL,
    morning_start text,
    morning_end text,
    afternoon_start text,
    afternoon_end text,
    total_hours numeric(4,1) DEFAULT 0 NOT NULL
);


--
-- Name: workflow_event_log; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workflow_event_log (
    id text NOT NULL,
    company_id text NOT NULL,
    entity_type public."WorkflowEntityType" NOT NULL,
    entity_id text NOT NULL,
    actor_id text NOT NULL,
    action text NOT NULL,
    phase public."WorkflowEventPhase" NOT NULL,
    before_state jsonb DEFAULT '{}'::jsonb NOT NULL,
    after_state jsonb DEFAULT '{}'::jsonb NOT NULL,
    reason text,
    correlation_id text,
    corrects_event_id text,
    created_at timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


